import 'package:supabase_flutter/supabase_flutter.dart';
class CreditBalance{const CreditBalance({required this.transactionId,required this.transactionNo,required this.total,required this.paid,required this.balance,this.dueDate});final String transactionId,transactionNo;final double total,paid,balance;final DateTime? dueDate;factory CreditBalance.fromMap(Map<String,dynamic> r)=>CreditBalance(transactionId:r['transaction_id'] as String,transactionNo:r['transaction_no'] as String,total:(r['total'] as num).toDouble(),paid:(r['paid'] as num).toDouble(),balance:(r['balance'] as num).toDouble(),dueDate:r['due_date']==null?null:DateTime.parse(r['due_date'] as String));}
class CreditRepository{final _c=Supabase.instance.client;Future<List<CreditBalance>> load(String businessId)async{final rows=await _c.from('irkop_cell_credit_balances').select().eq('business_id',businessId).gt('balance',0).order('due_date');return rows.map<CreditBalance>((r)=>CreditBalance.fromMap(r)).toList();}Future<void> pay({required String businessId,required CreditBalance credit,required double amount,String? notes}){if(amount<=0)throw StateError('Nominal pembayaran harus lebih dari 0.');if(amount>credit.balance)throw StateError('Nominal pembayaran melebihi sisa kasbon.');return _c.from('irkop_cell_credit_payments').insert({'business_id':businessId,'transaction_id':credit.transactionId,'amount':amount,'notes':notes?.trim().isEmpty??true?null:notes!.trim()});}}